insert into public.learning_task_set_versions(id,curriculum_release_id,unit_id,source_family_id,locale,title,stimulus,members,source_reference,permission_reference,review_reference,reviewed_by,reviewed_at) select id,curriculum_release_id,unit_id,source_family_id,locale,title,stimulus,members,source_reference,permission_reference,review_reference,reviewed_by,reviewed_at from jsonb_populate_recordset(null::public.learning_task_set_versions,'[{"id":"53e03c8f-cdbd-5aa2-a60a-b8fcc65d7b8a","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"666623ab-ba5a-5ef1-908c-edccbd629963","locale":"en","title":"Reading source DB-A","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"A school club planned a clothes-swap afternoon. Its first notice asked people to bring fashionable clothes. Several students were unsure: did their clothes have to be popular that month?\n\nThe club rewrote the notice. It now asked for clean clothes in good condition, with the size written on a card. People could choose according to fit and personal preference. The club did not select one winning style.\n\nStudents who had misunderstood the first notice now knew what they could bring. A clear description of the event was more useful than a vague fashion label."},"members":[{"itemId":"20494a22-562a-5b72-ab04-a317bc96ca31","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"},{"itemId":"48c7dcad-4c3d-5c13-a79e-8b941a39727a","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-DB-READ-A; Original authored fiction within Unit 1 topics; all facts needed to answer are supplied.","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original platform-authored fictional passage within the Unit 1 topic.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"},{"id":"4122df4c-e8c5-53eb-a399-68b4c13d511b","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"e2ea2323-9ab3-59c7-ade7-9a125b781075","locale":"en","title":"Reading source DB-B","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"The Fashion and Design Chamber of Armenia describes Inga Manukyan''s path to LOOM Weaving. During her art studies, Armenian carpet weaving gave her ideas for clothing. Later, with encouragement from her sister, she developed that idea further. The sisters started LOOM Weaving in 2014.\n\nThe profile connects their knitwear with handmade techniques and modern style. It shows one way a traditional craft can inspire clothing made for the present."},"members":[{"itemId":"306106fb-7445-504d-a45c-480f64279eb3","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"},{"itemId":"3965e2fa-2ab5-5a0e-a3dc-7d056f7c3a0f","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-DB-READ-B; Original short factual paraphrase of the cited primary FDC profile, checked 2026-10-22; no photograph, marketing ranking or endorsement reused.; https://www.fdc.am/designers/5","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original attributed factual paraphrase. Primary-source provenance is retained; no photograph, verbatim external passage, endorsement or third-party licence is imported.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"},{"id":"a97cd981-775b-5fa5-a2eb-4ffec2a9ce2d","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"4c308062-c912-5aca-8f99-1fcf33e96d75","locale":"en","title":"Reading source MB-A","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"For a class project, Lilit photographed three people wearing the same borrowed coat. She expected their written descriptions of it to be alike. Instead, one person praised the deep pockets, another liked the bright lining, and the third said the coat was difficult to move in.\n\nLilit kept all three comments beside the photographs. The project was about people''s different experiences, so she did not replace the comments with one score for the coat. Readers could see what mattered to each person."},"members":[{"itemId":"aeed9a93-bff7-573d-a9c8-7181dbd1812a","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"},{"itemId":"6e3f62bb-280d-5c17-aaf4-9fec555cdf87","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-MB-READ-A; Original authored fiction within Unit 1 topics; all facts needed to answer are supplied.","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original platform-authored fictional passage within the Unit 1 topic.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"},{"id":"5c38a61c-987a-5bf1-a368-fc28711361ec","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"546febe1-e048-5fc7-b66d-2023f636dc5c","locale":"en","title":"Reading source MB-B","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"According to the Fashion and Design Chamber of Armenia, SHABEEG uses clothing to share Armenian heritage. Nature, architecture and traditional dress provide ideas for its designs. Its products include T-shirts as well as other clothes and bags.\n\nThe profile describes a clear design sequence: the pictures are first drawn by hand and then turned into digital images. Traditional sources of inspiration and a later digital step are both part of the account."},"members":[{"itemId":"ce4a9c9a-cfc0-5b5c-a1de-a755c7714d24","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"},{"itemId":"3906ff32-0913-5ae7-a44c-2fb712a31b39","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-MB-READ-B; Original short factual paraphrase of the cited primary FDC profile, checked 2026-10-22; no photograph, marketing ranking or endorsement reused.; https://www.fdc.am/designers/6","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original attributed factual paraphrase. Primary-source provenance is retained; no photograph, verbatim external passage, endorsement or third-party licence is imported.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"},{"id":"9cc705fc-47d6-5fa4-a3d9-e07e66e2a759","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"a0f73378-c629-58d1-a194-2e6f443cb43f","locale":"en","title":"Reading source MC-A","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"A class prepared a guide to costumes for visitors who would not see the display. The first draft said only that each costume was beautiful or unusual. When a classmate read it without the photographs, those words did not help her imagine the clothes.\n\nThe writers added colours, shapes and parts such as collars and sleeves. They kept opinions in a separate final sentence. For one jacket, they described a short green body with long yellow sleeves. The revised guide gave readers concrete information before offering an opinion."},"members":[{"itemId":"5c2ee852-5f61-5659-a0e3-f5c03207eae4","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"},{"itemId":"beea1d76-3417-5a78-a57c-e1f6df748369","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-MC-READ-A; Original authored fiction within Unit 1 topics; all facts needed to answer are supplied.","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original platform-authored fictional passage within the Unit 1 topic.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"},{"id":"f6b3cc18-daf8-5808-a25d-a9c4e2f2dbfa","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"a864e540-7a9e-533f-9bca-06febf414330","locale":"en","title":"Reading source MC-B","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"The Fashion and Design Chamber of Armenia describes two connected activities at the Teryan Cultural Center. One is carefully recreating traditional Armenian clothing with advice from experts who study culture and traditions. Another is making modern clothes and accessories that use traditional elements.\n\nThe center also offers opportunities to learn traditional crafts. In this account, preserving older designs and using cultural ideas in present-day work are connected, but they are not described as exactly the same activity."},"members":[{"itemId":"2f4b61d0-d3ac-5dd4-a7ec-e5b1c6afb159","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"},{"itemId":"72afd1f2-8f45-5e64-a1fe-d0e7ec69870a","version":2,"skillId":"8cb750f3-24b2-5ea6-a058-054199b4fc8a"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-MC-READ-B; Original short factual paraphrase of the cited primary FDC profile, checked 2026-10-22; no photograph, marketing ranking or endorsement reused.; https://www.fdc.am/designers/45","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original attributed factual paraphrase. Primary-source provenance is retained; no photograph, verbatim external passage, endorsement or third-party licence is imported.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"}]'::jsonb);
