select * into registered_set from public.learning_task_set_versions where id='53e03c8f-cdbd-5aa2-a60a-b8fcc65d7b8a';
 if not to_jsonb(registered_set) @> ('{"id":"53e03c8f-cdbd-5aa2-a60a-b8fcc65d7b8a","curriculum_release_id":"e40991ee-ca0b-5666-a9f2-a3453de8fccb","unit_id":"3ef44139-0053-58e6-ab0d-5901a0213683","source_family_id":"666623ab-ba5a-5ef1-908c-edccbd629963","locale":"en","title":"Reading source DB-A","stimulus":{"kind":"text","schemaVersion":"haiedu-text-v1","locale":"en","content":"A school club planned a clothes-swap afternoon. Its first notice asked people to bring fashionable clothes. Several students were unsure: did their clothes have to be popular that month?\n\nThe club rewrote the notice. It now asked for clean clothes in good condition, with the size written on a card. People could choose according to fit and personal preference. The club did not select one winning style.\n\nStudents who had misunderstood the first notice now knew what they could bring. A clear description of the event was more useful than a vague fashion label."},"members":[{"itemId":"20494a22-562a-5b72-ab04-a317bc96ca31","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"},{"itemId":"48c7dcad-4c3d-5c13-a79e-8b941a39727a","version":2,"skillId":"06fbe791-0e40-5192-adcf-496f96b45bba"}],"source_reference":"docs/content/english-7-unit-01-assessment-batch-bcd.json#ENG7-U01-DB-READ-A; Original authored fiction within Unit 1 topics; all facts needed to answer are supplied.","permission_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; Owner accepts use of this original platform-authored fictional passage within the Unit 1 topic.","review_reference":"docs/evidence/english-7-unit-01-bcd-reading-acceptance-20261022.json#0df2795c087c5290faf07950e80ed8d2e968b85ae2f48099a12deb74a51571a7; owner accepted exact source for MVP; delegated registration","reviewed_by":"67b9165f-9186-4746-a5e3-2f97c3cf0dfc","reviewed_at":"2026-10-22 07:12:02.97279+00"}'::jsonb-'reviewed_at') or registered_set.reviewed_at<>'2026-10-22 07:12:02.97279+00'::timestamptz then raise exception 'C14 source mismatch'; end if;
 select array_agg((value->>'itemId')::uuid order by ordinality) into expected_order from jsonb_array_elements(registered_set.members) with ordinality;
